<?php $p=$product; ?>
<section class="page-heading"><div><h1><?= e($p['name']) ?></h1><p><?= e($p['sku']) ?> · <?= $p['archived_at']?'Archived':e(ucfirst($p['status'])) ?></p></div><div class="product-actions"><a class="button" href="<?= e(url('/products')) ?>">All products</a><?php if(!$p['archived_at']): ?><a class="button" href="<?= e(url('/products/form')) ?>&amp;id=<?= (int)$p['id'] ?>">Edit</a><?php endif; ?><a class="button button-primary" href="<?= e(url('/products/form')) ?>&amp;duplicate=<?= (int)$p['id'] ?>">Duplicate product</a></div></section>
