<div class="product-form-grid"><section class="surface product-section"><h2>Product information</h2><dl class="product-facts"><?php foreach(['category_name'=>'Category','subcategory_name'=>'Subcategory','brand_name'=>'Brand','part_number'=>'OEM / part number','aliases'=>'Search aliases','rack_location'=>'Rack','hsn_code'=>'HSN','description'=>'Description'] as $key=>$label): ?><dt><?= e($label) ?></dt><dd><?= e($p[$key]??'') ?: '—' ?></dd><?php endforeach; ?><?php foreach($p['specifications'] as $spec): ?><dt><?= e($spec['label']) ?></dt><dd><?= e($spec['value']) ?></dd><?php endforeach; ?></dl></section><section class="surface product-section"><h2>Pricing &amp; stock</h2><dl class="product-facts"><dt>Purchase price</dt><dd><?= money($p['purchase_price']) ?></dd><dt>Selling price</dt><dd><?= money($p['selling_price']) ?></dd><dt>MRP</dt><dd><?= $p['mrp']===null?'—':money($p['mrp']) ?></dd><dt>Tax rate</dt><dd><?= $p['tax_rate']===null?'Not configured':e($p['tax_rate']).'%' ?></dd><dt>Available stock</dt><dd><?= $p['quantity']===null?'Not tracked':quantity($p['quantity']) ?></dd><dt>Minimum stock</dt><dd><?= quantity($p['reorder_level']) ?></dd><dt>Average stock cost</dt><dd><?= $p['average_unit_cost']===null?'—':money($p['average_unit_cost']) ?></dd></dl><p class="subtle-text">Editing product information does not change stock. Subsequent stock changes belong in inventory operations.</p><?php if(!$p['archived_at']): ?><form method="post" action="<?= e(url('/products/archive')) ?>" data-product-confirm="Archive this product? Inventory and transactions will be preserved."><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="danger-button">Archive product</button></form><?php endif; ?></section>
<section class="surface product-section wide"><h2>Compatible bikes</h2><?php if(!$p['fitments']): ?><p class="subtle-text">No compatibility claims recorded.</p><?php endif; ?><div class="table-scroll"><table><thead><tr><th>Manufacturer / model</th><th>Variant</th><th>Years</th><th>Fitment notes</th><th>Verification</th></tr></thead><tbody><?php foreach($p['fitments'] as $f): ?><tr><td><?= e($f['manufacturer_name'].' '.$f['model_name']) ?></td><td><?= e($f['variant_name']??'Not specified') ?></td><td><?= e((string)($f['year_from']??'Any')) ?> – <?= e((string)($f['year_to']??'Any')) ?></td><td><?= e($f['notes']) ?></td><td><?= $f['verified_at']?'Verified · '.e(local_datetime($f['verified_at'])):'Unverified' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="surface product-section wide"><h2>Stock movement history <span class="subtle-text">latest 50</span></h2><div class="table-scroll"><table><thead><tr><th>Date</th><th>Movement</th><th class="number">Quantity</th><th class="number">Cost per item</th><th>Reference</th></tr></thead><tbody><?php foreach($p['movements'] as $m): ?><tr><td><?= e(local_datetime($m['created_at'])) ?></td><td><?= e(ucfirst($m['movement_type'])) ?></td><td class="number"><?= quantity($m['quantity_delta']) ?></td><td class="number"><?= money($m['unit_cost']) ?></td><td><?= e(($m['reference_type']??'').' '.($m['reference_id']??'')) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$p['movements']): ?><p class="subtle-text">No stock movements recorded.</p><?php endif; ?></div></section></div>
